type StatSource = Pick<ProvinceStat, 'code' | 'name' | 'officialCountLabel' | 'officialCountType' | 'officialScope' | 'matchLevel' | 'note'> & Partial<Pick<ProvinceStat, 'sourceUrl' | 'sourceDate' | 'publishedCount' | 'verifiedCount' | 'pendingCount'>>

const stat = (item: StatSource): ProvinceStat => ({
  publishedCount: item.publishedCount ?? null,
  verifiedCount: item.verifiedCount ?? null,
  pendingCount: item.pendingCount ?? 0,
  status: item.officialCountLabel ? 'published' : 'pending',
  coverage: item.officialCountLabel ? '已整理的时期统计；具体范围以统计口径和备注为准' : '当前无可靠统计，空值不代表0人',
  updatedAt: '2026-10-10',
  ...item,
})

