const makeContributionSummary = (person: PersonSummary): string => {
  const death = person.deathYear
    ? `牺牲年份记载为${person.deathYear}年；`
    : ''

  return `资料摘要：来源记录将其列为${person.category}；${death}具体事迹以${person.sourceLabel.replace('来源：', '')}所对应的原始资料为准。`
}

export const people: PersonSummary[] = peopleRecords.map(person => ({
  ...person,
  contribution: person.contribution || makeContributionSummary(person),
}))

